"""Generated by Riffle from a 1-qubit circuit."""
from guppylang import guppy
from guppylang.std.quantum import qubit, measure, discard, h, rz, angle
from guppylang.std.builtins import result


@guppy
def main() -> None:
    q0 = qubit()
    h(q0)  # a
    rz(q0, angle(0.5))  # dial
    h(q0)  # out
    result("c0", measure(q0).read())
